<?php
function overview_export_meta($r){return ['Period'=>$r['filters']['from'].' to '.$r['filters']['to'],'Filters'=>report_readable_filters($r['filters']),'Generated'=>$r['generated'],'Generated By'=>$r['user'],'Quantity Unit'=>'pcs','Basis'=>'Posted transaction dates; all matching products across every page.'];}
function overview_export_sections($r){return [
 ['name'=>'Ending Totals','headers'=>['Metric','Quantity (pcs)'],'rows'=>array_map(fn($label,$qty)=>[$label,(int)$qty],array_keys($r['summary']),array_values($r['summary']))],
 ['name'=>'Product Summary','headers'=>$r['headers'],'rows'=>report_export_rows($r)],
 ['name'=>'Movement Breakdown','headers'=>['Movement','Sellable (pcs)','Non-Sellable (pcs)','Physical (pcs)'],'rows'=>overview_matrix_rows($r['overview']['rollforward'],$r['filters'])]
 ];}
/** Reuses the existing typed/escaped XLSX writer, then combines its worksheets. */
function overview_write_xlsx($path,$r){
 $sections=overview_export_sections($r);$meta=overview_export_meta($r);$meta['Notes']=implode(' ',$r['notes']);$sheets=[];$styles='';$temporary=[];
 try{
  foreach($sections as $section){$temp=tempnam(sys_get_temp_dir(),'rs8-overview-');if($temp===false)throw new Exception('Temporary report storage unavailable.');$temporary[]=$temp;
   report_write_xlsx($temp,$section['name'],$section['headers'],$section['rows'],$meta);$input=new ZipArchive();if($input->open($temp)!==true)throw new Exception('Cannot read generated report.');try{$xml=$input->getFromName('xl/worksheets/sheet1.xml');$style=$input->getFromName('xl/styles.xml');if($xml===false||$style===false)throw new Exception('Generated report is incomplete.');$sheets[]=$xml;if($styles==='')$styles=$style;}finally{$input->close();}
  }
  $xmlEscape=fn($value)=>htmlspecialchars((string)$value,ENT_XML1|ENT_QUOTES,'UTF-8');
  $types='<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>';
  $workbook='<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>';
  $rels='<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">';
  $out=new ZipArchive();if($out->open($path,ZipArchive::CREATE|ZipArchive::OVERWRITE)!==true)throw new Exception('Cannot create Overview workbook.');
  try{foreach($sections as $i=>$section){$id=$i+1;$types.='<Override PartName="/xl/worksheets/sheet'.$id.'.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>';$workbook.='<sheet name="'.$xmlEscape($section['name']).'" sheetId="'.$id.'" r:id="rId'.$id.'"/>';$rels.='<Relationship Id="rId'.$id.'" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet'.$id.'.xml"/>';$out->addFromString('xl/worksheets/sheet'.$id.'.xml',$sheets[$i]);}
   $rels.='<Relationship Id="rId'.(count($sections)+1).'" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>';
   $out->addFromString('[Content_Types].xml',$types.'</Types>');$out->addFromString('xl/workbook.xml',$workbook.'</sheets></workbook>');$out->addFromString('xl/_rels/workbook.xml.rels',$rels);$out->addFromString('xl/styles.xml',$styles);$out->addFromString('_rels/.rels','<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>');
  }finally{if(!$out->close())throw new Exception('Overview workbook could not be saved.');}
 }finally{foreach($temporary as $temp)if(is_file($temp))unlink($temp);}
}
function overview_print_document($r){
 echo '<!doctype html><html lang="en"><head><meta charset="utf-8"><title>Inventory Operations Summary</title><style>body{font:12px Arial,sans-serif;color:#16263c;margin:24px}h1{font-size:22px}h2{font-size:17px;margin-top:24px}table{width:100%;border-collapse:collapse;margin:10px 0 20px}th,td{padding:8px;border-bottom:1px solid #cfd8e3;text-align:left;overflow-wrap:anywhere}th{background:#edf2f7}thead{display:table-header-group}tr{break-inside:avoid}.number{text-align:right;font-variant-numeric:tabular-nums}.meta,.notes{line-height:1.7;margin:12px 0}.notes{color:#53647a}tfoot{font-weight:bold}@page{size:A4 landscape;margin:12mm}@media print{button{display:none}}</style></head><body><button onclick="window.print()">Print / Save as PDF</button><h1>Inventory Operations Summary</h1><b>E-commerce Inventory Management System</b><div class="meta">';foreach(overview_export_meta($r) as $key=>$value)echo e($key).': '.e($value).'<br>';echo '</div>';
 foreach(overview_export_sections($r) as $section){[$headers,$rows]=export_current_product_details($section['headers'],$section['rows']);echo '<h2>'.e($section['name']).'</h2><table><thead><tr>';foreach($headers as $header)echo '<th>'.e($header).'</th>';echo '</tr></thead><tbody>';foreach($rows as $row){echo '<tr>';foreach($row as $value)echo '<td'.(is_numeric($value)?' class="number"':'').'>'.e(is_int($value)?number_format($value):$value).'</td>';echo '</tr>';}echo '</tbody></table>';}
 echo '<div class="notes">';foreach($r['notes'] as $note)echo '<p>'.e($note).'</p>';echo '</div></body></html>';
}
